"""`.KK alphamask parser`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.KK alphamask parser'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Value', 'NodeSocketFloat')
    t.socket('INPUT', 'Alphamask color', 'NodeSocketColor', default_value=(0.8, 0.8, 0.8, 1.0))
    t.socket('INPUT', 'Alphamask alpha', 'NodeSocketFloat', default_value=0.5, min_value=-10000.0, max_value=10000.0)
    t.socket('INPUT', 'Light image alpha', 'NodeSocketFloat', default_value=0.5, min_value=-10000.0, max_value=10000.0)
    t.socket('INPUT', 'Force visibility?', 'NodeSocketFloat', default_value=0.5, min_value=-10000.0, max_value=10000.0)

    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (623.6505, 163.05707),
    })
    t.node('NodeGroupInput', 'Group Input', props={
        'location': (-599.6091, 213.36626),
    })
    t.node('ShaderNodeSeparateColor', 'Separate Color', props={
        'location': (-431.4922, -107.32654),
        'hide': True,
    })
    t.node('ShaderNodeMath', 'Red', props={
        'location': (-216.75008, -123.33701),
        'hide': True,
        'operation': 'MULTIPLY',
        'use_clamp': True,
    })
    t.node('ShaderNodeMath', 'Math.002', props={
        'location': (428.19458, 141.92383),
        'hide': True,
        'operation': 'MULTIPLY',
        'use_clamp': True,
    })
    t.node('ShaderNodeMath', 'Disable', inputs={'Value_001': 1.0}, props={
        'location': (-212.76262, 69.02537),
        'hide': True,
        'operation': 'LESS_THAN',
        'use_clamp': True,
    })
    t.node('ShaderNodeMath', 'Stage0', inputs={'Value_001': 2.0}, props={
        'location': (-209.44186, 11.736768),
        'hide': True,
        'operation': 'LESS_THAN',
        'use_clamp': True,
    })
    t.node('ShaderNodeMath', 'Green', props={
        'location': (-214.74577, -83.64583),
        'hide': True,
        'operation': 'MULTIPLY',
        'use_clamp': True,
    })
    t.node('ShaderNodeMath', 'Stage1', inputs={'Value_001': 3.0}, props={
        'location': (-211.73926, -34.951035),
        'hide': True,
        'operation': 'LESS_THAN',
        'use_clamp': True,
    })
    t.node('ShaderNodeMath', 'Math.007', inputs={'Value_001': 1.0}, props={
        'location': (285.003, 43.970596),
        'hide': True,
        'operation': 'MAXIMUM',
        'use_clamp': True,
    })
    t.node('ShaderNodeMath', 'Math.008', props={
        'location': (-25.343555, -13.7845),
        'hide': True,
        'operation': 'MULTIPLY',
    })
    t.node('ShaderNodeMath', 'Math.009', props={
        'location': (-24.034027, -71.01149),
        'hide': True,
        'operation': 'MULTIPLY',
    })
    t.node('ShaderNodeMath', 'Math.010', inputs={'Value_001': 1.0}, props={
        'location': (135.10477, -36.973724),
        'hide': True,
        'operation': 'MAXIMUM',
        'use_clamp': True,
    })
    t.node('ShaderNodeMapRange', 'Map Range', inputs={'From Min': 0.05}, props={
        'location': (216.82184, 141.33054),
        'hide': True,
        'interpolation_type': 'SMOOTHSTEP',
    })

    t.link('Stage1', 'Value', 'Math.009', 'Value')
    t.link('Math.007', 'Value', 'Math.002', 'Value_001')
    t.link('Separate Color', 'Red', 'Red', 'Value')
    t.link('Separate Color', 'Green', 'Green', 'Value')
    t.link('Math.009', 'Value', 'Math.010', 'Value_001')
    t.link('Math.008', 'Value', 'Math.010', 'Value')
    t.link('Math.010', 'Value', 'Math.007', 'Value_001')
    t.link('Disable', 'Value', 'Math.007', 'Value')
    t.link('Stage0', 'Value', 'Math.008', 'Value')
    t.link('Group Input', 'Force visibility?', 'Disable', 'Value')
    t.link('Group Input', 'Force visibility?', 'Stage0', 'Value')
    t.link('Group Input', 'Force visibility?', 'Stage1', 'Value')
    t.link('Group Input', 'Alphamask color', 'Separate Color', 'Color')
    t.link('Map Range', 'Result', 'Math.002', 'Value')
    t.link('Group Input', 'Alphamask alpha', 'Red', 'Value_001')
    t.link('Group Input', 'Alphamask alpha', 'Green', 'Value_001')
    t.link('Math.002', 'Value', 'Group Output', 'Value')
    t.link('Red', 'Value', 'Math.009', 'Value_001')
    t.link('Green', 'Value', 'Math.008', 'Value_001')
    t.link('Group Input', 'Light image alpha', 'Map Range', 'Value')
    return t
